import json, os, re, sqlite3
from pathlib import Path
from collections import Counter, defaultdict
root=Path(os.environ['RUN_TMP'])
courses=json.loads((root/'courses_raw.json').read_text())
con=sqlite3.connect('file:'+os.environ['DB_PATH']+'?mode=ro', uri=True)
rows=con.execute('select id,slug,name,parent_id from career_nodes').fetchall()
nodes={r[0]:r for r in rows}; by_slug={r[1]:r for r in rows}
def breadcrumb(slug):
    r=by_slug[slug]; out=[]
    while r:
        out.append(r[2])
        r=nodes.get(r[3]) if r[3] is not None else None
    return ' > '.join(reversed(out))

def clean(n):
    return re.sub(r'\\s+', ' ', n.lower().replace('&',' and ')).strip()

def classify(name, cat):
    n=clean(name)
    # explicit non-degree and medical/health matches first
    if 'yoga instructor' in n:
        return 'sports_career','nearest_parent','medium'
    if 'music therapy' in n:
        return 'music_course','nearest_parent','medium'
    if 'graphology' in n or 'crime scene' in n or 'forensic photography' in n or 'social media crimes' in n or 'forensic science' in n or 'forensic' in n:
        return 'bsc_forensic','direct_discipline' if ('forensic science' in n or 'forensic' in n and ('b.sc' in n or 'bsc' in n)) else 'nearest_parent','high' if 'forensic science' in n and cat=='undergraduate' else 'medium'
    if 'pharmacy' in n:
        return 'bpharm','direct_discipline' if ('bachelor of pharmacy' in n or 'b.pharm' in n) else 'nearest_parent','high' if ('bachelor of pharmacy' in n or 'b.pharm' in n) else 'medium'
    if 'nursing' in n:
        return 'bsc_nursing','direct_discipline' if ('b.sc' in n or 'bsc' in n) else 'nearest_parent','high' if ('b.sc' in n or 'bsc' in n) else 'medium'
