        return 'bba','direct_discipline' if 'bba' in n and cat=='undergraduate' and 'integrated mba' not in n else 'nearest_parent','high' if 'bba' in n and cat=='undergraduate' and 'integrated mba' not in n else 'medium'
    # design
    if 'design' in n or 'fashion' in n:
        return 'bdes','direct_discipline' if ('b.des' in n or 'b. des' in n) and cat=='undergraduate' else 'nearest_parent','high' if ('b.des' in n or 'b. des' in n) and cat=='undergraduate' else 'medium'
    # education
    if 'b.ed' in n or 'b.a. b.ed' in n or 'b.sc. b.ed' in n or 'education' in n:
        return 'ba_education','direct_discipline' if ('b.ed' in n or 'b.a. b.ed' in n or 'b.sc. b.ed' in n) and cat=='undergraduate' else 'nearest_parent','high' if cat=='undergraduate' and ('b.ed' in n or 'b.a. b.ed' in n or 'b.sc. b.ed' in n) else 'medium'
    # languages, arts, media, humanities
    if any(x in n for x in ['journalism','mass communication','media and communication','strategic communication','digital media','anchoring','journalism']):
        return 'bjmc','direct_discipline' if cat=='undergraduate' else 'nearest_parent','high' if cat=='undergraduate' else 'medium'
