    if 'sociology' in n or 'social work' in n: return 'ba_sociology','direct_discipline' if cat=='undergraduate' else 'nearest_parent','high' if cat=='undergraduate' else 'medium'
    if 'political' in n or 'public policy' in n or 'governance' in n: return 'ba_polsci','direct_discipline' if cat=='undergraduate' else 'nearest_parent','high' if cat=='undergraduate' else 'medium'
    if 'economics' in n: return 'ba_economics','direct_discipline' if cat=='undergraduate' else 'nearest_parent','high' if cat=='undergraduate' else 'medium'
    if 'english' in n: return 'ba_english','direct_discipline' if cat=='undergraduate' else 'nearest_parent','high' if cat=='undergraduate' else 'medium'
    if any(x in n for x in ['french','japanese','foreign language']): return 'ba_foreign_lang','direct_discipline' if cat=='undergraduate' else 'nearest_parent','high' if cat=='undergraduate' else 'medium'
    if 'history' in n: return 'ba_history','direct_discipline' if cat=='undergraduate' else 'nearest_parent','high' if cat=='undergraduate' else 'medium'
